def fix(df):
    q = np.abs(df['Usage_kWh']) * np.sqrt(np.maximum((100.0 / df['Lagging_Current_Power_Factor']) ** 2 - 1.0, 0.0))
    return q.replace([np.inf, -np.inf], 1e308).fillna(0.0)

def fix(df):
    p = df['Usage_kWh'].astype(float)
    f = df['Leading_Current_Power_Factor'].astype(float)
    f_safe = np.clip(f, 0.03, 100.0)
    return (np.abs(p) * np.sqrt(np.maximum((100.0 / f_safe) ** 2 - 1.0, 0.0))).astype(float)
